            verificationGrade = "Official State Historical Marker & National Civil Rights Landmark",
            geofenceRadiusMeters = 150,
            audioNarration = "You are at Freeman Field. In April 1945, 101 Black officers of the Tuskegee Airmen staged a courageous stand against segregated officers' clubs here, accelerating the desegregation of the United States military.",
